/// <summary>
/// Event handler class for <c>PriceDiscAdmTable</c> form
/// </summary>
class GUPPriceDiscAdmTableFormEventHandler
{
}

Method.Source:
/// <summary>
/// Override lookup for journal called from unified pricing service
/// </summary>
/// <param name="_sender">Sender control</param>
/// <param name="_e">Param</param>
[FormControlEventHandler(formControlStr(PriceDiscAdmTable, PriceDiscAdmTable_JournalName), FormControlEventType::Lookup)]
public static void PriceDiscAdmTable_JournalName_OnLookup(FormControl _sender, FormControlEventArgs _e)
{
    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        SysTableLookup          sysTableLookup  = SysTableLookup::newParameters(tableNum(PriceDiscAdmName), _sender);
        Query                   query           = new Query();
        QueryBuildDataSource    qbds            = query.addDataSource(tableNum(PriceDiscAdmName));

        if (_sender.formRun().args().menuItemName() == menuItemDisplayStr(GUPPriceDiscAdmTable_Sales))
        {
            qbds.addRange(fieldNum(PriceDiscAdmName, DefaultRelation)).value(queryValue(PriceType::PriceSales));
        }

        sysTableLookup.addLookupfield(fieldNum(PriceDiscAdmName, JournalName));
        sysTableLookup.addLookupfield(fieldNum(PriceDiscAdmName, Name));

        sysTableLookup.parmQuery(query);
        sysTableLookup.performFormLookup();

        FormControlCancelableSuperEventArgs ce = _e as FormControlCancelableSuperEventArgs;

        ce.CancelSuperCall();
    }
}

[FormControlEventHandler(formControlStr(PriceDiscAdmTable, PriceDiscAdmTable_PriceComponentCombination), FormControlEventType::Lookup)]
public static void PriceDiscAdmTable_PriceComponentCombination_OnLookup(FormControl _sender, FormControlEventArgs _e)
{
    SysReferenceTableLookup sysReferenceTableLookup;
    Query                   query = new Query();
    QueryBuildDataSource    qbdsGroupCombination = query.addDataSource(tableNum(GUPPriceComponentCodePriceAttributeGroupCombination));
    QueryBuildDataSource    qbdsComponent;

    sysReferenceTableLookup = SysReferenceTableLookup::newParameters(tableNum(GUPPriceComponentCodePriceAttributeGroupCombination), _sender);
    sysReferenceTableLookup.addLookupfield(fieldNum(GUPPriceComponentCodePriceAttributeGroupCombination, Name));
    sysReferenceTableLookup.addLookupfield(fieldNum(GUPPriceComponentCodePriceAttributeGroupCombination, HeaderGroupAll));
    sysReferenceTableLookup.addLookupfield(fieldNum(GUPPriceComponentCodePriceAttributeGroupCombination, HeaderPriceAttributeGroup));
    sysReferenceTableLookup.addLookupfield(fieldNum(GUPPriceComponentCodePriceAttributeGroupCombination, LineGroupAll));
    sysReferenceTableLookup.addLookupfield(fieldNum(GUPPriceComponentCodePriceAttributeGroupCombination, LinePriceAttributeGroup));
    sysReferenceTableLookup.addLookupfield(fieldNum(GUPPriceComponentCodePriceAttributeGroupCombination, Priority));

    qbdsComponent = qbdsGroupCombination.addDataSource(tableNum(GUPPriceComponentCode));
    qbdsComponent.relations(true);
    qbdsComponent.joinMode(JoinMode::ExistsJoin);

    qbdsComponent.addRange(fieldNum(GUPPriceComponentCode, PriceComponent)).value(queryValue(GUPPriceComponent::SalesTradeAgreement));

    qbdsGroupCombination.addOrderByField(fieldNum(GUPPriceComponentCodePriceAttributeGroupCombination, Priority), SortOrder::Descending);
    sysReferenceTableLookup.parmQuery(query);

    sysReferenceTableLookup.performFormLookup();

    FormControlCancelableSuperEventArgs ce = _e as FormControlCancelableSuperEventArgs;

    ce.CancelSuperCall();
}

[FormControlEventHandler(formControlStr(PriceDiscAdmTable, PriceDiscAdmTable_JournalName), FormControlEventType::Modified)]
public static void PriceDiscAdmTable_JournalName_OnModified(FormControl _sender, FormControlEventArgs _e)
{
    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        if (_sender.valueStr())
        {
            FormDataSource fdsPriceDiscTable = _sender.formRun().dataSource(formDataSourceStr(PriceDiscAdmTable, PriceDiscAdmTable));
            boolean priceAttributeEnabled = PriceDiscAdmName::find(_sender.valueStr()).PriceDiscPriceAttributeEnable;

            fdsPriceDiscTable.object(fieldNum(PriceDiscAdmTable, PriceComponentCombination)).allowEdit(priceAttributeEnabled);
            fdsPriceDiscTable.object(fieldNum(PriceDiscAdmTable, PriceApplyAdjustment)).allowEdit(priceAttributeEnabled);
        }
    }
}

/// <summary>
/// If form is called for Unified pricing service set pricing attributes fields to visible
/// </summary>
/// <param name="_sender">PriceDiscAdmTable form</param>
/// <param name="_e">Parameter</param>
[FormEventHandler(formStr(PriceDiscAdmTable), FormEventType::Initialized)]
public static void PriceDiscAdmTable_OnInitialized(xFormRun _sender, FormEventArgs _e)
{
    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        if (_sender.args().menuItemName() == menuItemDisplayStr(GUPPriceDiscAdmTable_Sales))
        {
            _sender.dataSource(formDataSourceStr(PriceDiscAdmTable, PriceDiscAdmTable)).object(fieldNum(PriceDiscAdmTable, DefaultRelation)).allowEdit(false);
            _sender.design().controlName(formControlStr(PriceDiscAdmTable, PriceDiscAdmTable_PriceDiscPriceAttributeEnable)).visible(true);
            _sender.dataSource(formDataSourceStr(PriceDiscAdmTable, PriceDiscAdmTable)).object(fieldNum(PriceDiscAdmTable, PriceApplyAdjustment)).visible(true);
            _sender.dataSource(formDataSourceStr(PriceDiscAdmTable, PriceDiscAdmTable)).object(fieldNum(PriceDiscAdmTable, PriceComponentCombination)).visible(true);
        }
        else
        {
            _sender.dataSource(formDataSourceStr(PriceDiscAdmTable, PriceDiscAdmTable)).object(fieldNum(PriceDiscAdmTable, PriceApplyAdjustment)).visible(false);
            _sender.dataSource(formDataSourceStr(PriceDiscAdmTable, PriceDiscAdmTable)).object(fieldNum(PriceDiscAdmTable, PriceComponentCombination)).visible(false);
        }
    }
}

/// <summary>
/// If form is called from Component - display all journals related to the component
/// </summary>
/// <param name="_sender">PriceDiscAdmTable form</param>
/// <param name="_e">Parameter</param>
[FormEventHandler(formStr(PriceDiscAdmTable), FormEventType::Activated)]
public static void PriceDiscAdmTable_OnActivated(xFormRun _sender, FormEventArgs _e)
{
    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        if (_sender.args().menuItemName() == menuItemDisplayStr(GUPPriceDiscAdmTable_Sales)
        && _sender.args().dataset() == tableNum(GUPPriceComponentCodePriceAttributeGroupCombination))
        {
            FormComboBoxControl allOpenPosted = _sender.design().controlName(formControlStr(PriceDiscAdmTable, AllOpenPosted));
            FormDataSource fdsPriceDiscTable = _sender.dataSource(formDataSourceStr(PriceDiscAdmTable, PriceDiscAdmTable));

            allOpenPosted.selection(AllOpenPosted::All);

            SysQuery::findOrCreateRange(fdsPriceDiscTable.queryBuildDataSource(), fieldnum(PriceDiscAdmTable, Posted)).value('');
            fdsPriceDiscTable.executeQuery();
        }
    }
}
